program2='''from collections import Counter

def _components(grid, bg):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=set()
            while q:
                x,y=q.pop(); cells.add((x,y))
                for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    a,b=p
                    if 0<=a<h and 0<=b<w and grid[a][b]==col and p not in seen:
                        seen.add(p); q.append(p)
            r0=min(x for x,y in cells); r1=max(x for x,y in cells)
            c0=min(y for x,y in cells); c1=max(y for x,y in cells)
            mask=tuple(tuple((r,c) in cells for c in range(c0,c1+1)) for r in range(r0,r1+1))
            out.append((col,cells,(r0,c0,r1,c1),mask))
    return out

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps=_components(grid,bg); keys=[]
    for comp in comps:
        color,cells,box,mask=comp; r0,c0,r1,c1=box; hh=r1-r0+1; ww=c1-c0+1
        rows=[r0+i for i,row in enumerate(mask) if all(row)]
        cols=[c0+j for j in range(ww) if all(mask[i][j] for i in range(hh))]
        if len(rows)==len(cols)==1 and len(cells)==hh+ww-1 and rows[0] in (r0,r1) and cols[0] in (c0,c1):
            keys.append((len(cells),comp,rows[0],cols[0]))
    if not keys: return [row[:] for row in grid]
    _,key,cr,cc=max(keys,key=lambda z:z[0]); keycol,_,kb,_=key
    r0,c0,r1,c1=kb; hh=r1-r0+1; ww=c1-c0+1
    horizontal=ww>=hh
    if horizontal:
        arm_sign=-1 if cc==c1 else 1
        target_sign=-arm_sign
    else:
        arm_sign=-1 if cr==r1 else 1
        target_sign=-arm_sign
    def side(box):
        a,b,c,d=box
        if horizontal: return target_sign*((b+d)/2-cc)
        return target_sign*((a+c)/2-cr)
    def direction_key(comp):
        color,cells,box,mask=comp; a,b,c,d=box
        # Target must be beyond the corner on the axis opposite the longer arm.
        if horizontal:
            return target_sign*((b+d)/2-cc)>0
        return target_sign*((a+c)/2-cr)>0
    other=[x for x in comps if x[1]!=key[1]]
    # Prefer a repeated silhouette on the side opposite the long arm.
    repeated=[]
    for x in other:
        if x[3]==key[3]: continue
        if sum(1 for y in other if y[3]==x[3])>=2 and direction_key(x):
            repeated.append(x)
    # More directly, a target silhouette occurs in at least two components in total.
    if not repeated:
        repeated=[x for x in other if direction_key(x) and sum(1 for y in comps if y[3]==x[3])>=2]
    if repeated:
        def axis_gap(comp):
            a,b,c,d=comp[2]
            if horizontal:
                return max(0, min(abs(cc-b),abs(cc-d)) if target_sign<0 else min(abs(cc-b),abs(cc-d)))
            return max(0, min(abs(cr-a),abs(cr-c)))
        target=min(repeated,key=lambda x:(axis_gap(x),abs(side(x)), -len(x[1])))
    else:
        # The L corner points toward one quadrant; choose the closest object in the opposite quadrant.
        short_sign = -1 if (cr==r0 if horizontal else cc==c0) else 1
        # Opposite direction of the shorter arm on the perpendicular axis.
        candidates=[]
        for x in other:
            a,b,c,d=x[2]
            if horizontal:
                p=((a+c)/2-cr)*short_sign
                ok=direction_key(x) and p>0
                primary=max(0, min(b,d)-c1-1) if target_sign>0 else max(0,c0-d-1)
                perp=max(0,a-r1-1) if short_sign>0 else max(0,r0-c-1)
            else:
                p=((b+d)/2-cc)*short_sign
                ok=direction_key(x) and p>0
                primary=max(0,a-r1-1) if target_sign>0 else max(0,r0-c-1)
                perp=max(0,b-c1-1) if short_sign>0 else max(0,c0-d-1)
            if ok: candidates.append((primary+perp,primary,perp,x))
        if candidates: target=min(candidates,key=lambda z:(z[0],z[1],z[2],-len(z[3][1])))[3]
        else:
            candidates=[x for x in other if direction_key(x)]
            if not candidates:return [row[:] for row in grid]
            target=min(candidates,key=lambda x:(abs(side(x)), -len(x[1])))
    a,b,c,d=target[2]; out=[row[:] for row in grid]
    for r in range(a,c+1):
        for col in range(b,d+1): out[r][col]=keycol
    return out
